export const npcAudioEntries: Record<string, Record<string, {sourceJa:string;role:string;speakerId:number;clip:string;durationMs:number}>> = {"SC-019-001": {"DLG-SC-019-001-SHARED-01": {"sourceJa": "放送が聞こえにくい場所ですね。行先を確認されますか。", "role": "youngMale", "speakerId": 11, "clip": "b33b99c818679eac663e840d5c4a9e243e89cef9336138c427a68a94e191b742", "durationMs": 4267}, "DLG-SC-019-001-SHARED-03": {"sourceJa": "乗る予定の駅名をお知らせください。", "role": "youngMale", "speakerId": 11, "clip": "bcad6602bf2e589c2b3dcef16a51040f2f5621a182eedc967a8f0f62db9f26bd", "durationMs": 2496}, "DLG-SC-019-001-SHARED-05": {"sourceJa": "ホームの表示と車両の行先を一緒に見比べましょう。", "role": "youngMale", "speakerId": 11, "clip": "6f400c25e32668c502a4b6b7bfa4fe5fa07e21415971597cc7075c545238ee88", "durationMs": 3595}, "DLG-SC-019-001-SHARED-07": {"sourceJa": "停車するかはこちらで確認します。黄色い線の内側でお待ちください。", "role": "youngMale", "speakerId": 11, "clip": "c00677414e98a8f7fa86e045b326313aea6baa7e1576918fc1166eb3ea440ff7", "durationMs": 5077}, "DLG-SC-019-001-SHARED-09": {"sourceJa": "確認できました。この列車はメモの駅に停車します。", "role": "youngMale", "speakerId": 11, "clip": "fec38571c6055652d86c39a8b8276108c13ff4f81ed19b53e04ca81e327c6811", "durationMs": 3808}, "DLG-SC-019-001-SHARED-11": {"sourceJa": "停車駅を確かめてから乗れますね。それでは、お気をつけて。", "role": "youngMale", "speakerId": 11, "clip": "77f8491a2681d26716d12afaad98ff208460ab6743d66e851a59f5f1b175cb53", "durationMs": 4640}}, "SC-032-001": {"DLG-SC-032-001-SHARED-01": {"sourceJa": "城内をご案内しますが、階段のある区間も含まれます。", "role": "adultMale", "speakerId": 21, "clip": "de135bde2edb6a33fab2f321e2b017a8b2a15136f1661c0b00f965b8ef357fc4", "durationMs": 4587}, "DLG-SC-032-001-SHARED-03": {"sourceJa": "それなら、ここにある案内図で石垣の見える場所を選びましょう。", "role": "adultMale", "speakerId": 21, "clip": "6028aef827a23af1eeef49e77002d6ba062b6e5d7b26be81ddef64bb5f3e2de2", "durationMs": 4907}, "DLG-SC-032-001-SHARED-05": {"sourceJa": "階段の印ですね。坂は斜線なので、この印のある道は避けてください。", "role": "adultMale", "speakerId": 21, "clip": "c85b083dd907f4c2fff307537d2f92d1b5b1071129e136de1bdd077d2bf20f2d", "durationMs": 6272}, "DLG-SC-032-001-SHARED-07": {"sourceJa": "図では右側の道がつながっていますが、今日の通行状況は入口で確認しましょう。", "role": "adultMale", "speakerId": 21, "clip": "a1f27ff8e712da8758da5465aff28a1c55463934692597a5771bcff52263ecbe", "durationMs": 6560}, "DLG-SC-032-001-SHARED-09": {"sourceJa": "通路をふさがないよう、そちらのベンチへどうぞ。", "role": "adultMale", "speakerId": 21, "clip": "1a11a1ed68ca4b5af745601c2f92c467dae3bf7abe6ef25cfd720b783497e308", "durationMs": 3584}, "DLG-SC-032-001-SHARED-11": {"sourceJa": "入口で確認してきますので、どうぞ少しお休みください。", "role": "adultMale", "speakerId": 21, "clip": "63eed01248c2c722b50fa91dc11e82db257dcfdd32c83a10deaa63eece3b649b", "durationMs": 4459}}, "SC-AIC-ICHINOMIYA-001": {"DLG-SC-AIC-ICHINOMIYA-001-SHARED-01": {"sourceJa": "織り始める前に、動きを練習しましょうか。", "role": "adultFemale", "speakerId": 118, "clip": "4b731f51b12fd6065cffa337701ace875052a3032020a281c34cabf4f89b2e57", "durationMs": 3915}, "DLG-SC-AIC-ICHINOMIYA-001-SHARED-03": {"sourceJa": "まず私が足元の動きを見せます。糸はまだ通さずにご覧ください。", "role": "adultFemale", "speakerId": 118, "clip": "94ada6bb5f8577da42328360605e82543e1d26cfe57563abcccec60267cb6dfb", "durationMs": 6080}, "DLG-SC-AIC-ICHINOMIYA-001-SHARED-05": {"sourceJa": "この位置でいったん止め、戻す動きまでを一組にします。", "role": "adultFemale", "speakerId": 118, "clip": "3713ec0e56cadba77d396904cfb392906f6fcb8e0133065f61453f0a005535d0", "durationMs": 4789}, "DLG-SC-AIC-ICHINOMIYA-001-SHARED-07": {"sourceJa": "では、私の合図で一度だけ試してください。", "role": "adultFemale", "speakerId": 118, "clip": "23768102c861d8485e9d3cc394efc2c7882de20de6531c7c7aafea92411df5b5", "durationMs": 4053}, "DLG-SC-AIC-ICHINOMIYA-001-SHARED-09": {"sourceJa": "よいですよ。手と合わせるのは、その練習が済んでからにしましょう。", "role": "adultFemale", "speakerId": 118, "clip": "b012c2317b4aa97526fe67cec72c4286390f059162199fd3960e2241a99c7d3e", "durationMs": 5739}, "DLG-SC-AIC-ICHINOMIYA-001-SHARED-11": {"sourceJa": "今日は足の練習までにしましょう。次は手の動きを説明します。お疲れさまでした。それでは、またお待ちしています。", "role": "adultFemale", "speakerId": 118, "clip": "83ec3b4efc35b2b37ab5a30c75c47c342b392b3c2e8b2bc3094753f798968ecc", "durationMs": 10549}}, "SC-AKT-SEMBOKU-001": {"DLG-SC-AKT-SEMBOKU-001-SHARED-01": {"sourceJa": "いらっしゃいませ。何かお手伝いできますか。", "role": "femaleStudent", "speakerId": 8, "clip": "41d479cf1789825a9cf74a741a81eba86201dbaf9773af601264a72a1f360c7e", "durationMs": 3595}, "DLG-SC-AKT-SEMBOKU-001-SHARED-03": {"sourceJa": "お持ちの帯を広げて確認しましょう。どこを正面だと思って巻きましたか。", "role": "femaleStudent", "speakerId": 8, "clip": "495ccb6bd90c0949648da7f4b4782a0b518239395d1cb3872d94c061ef1537f7", "durationMs": 5536}, "DLG-SC-AKT-SEMBOKU-001-SHARED-05": {"sourceJa": "仕上がりの位置を相談しましょう。帯を切って柄を移すのではありません。", "role": "femaleStudent", "speakerId": 8, "clip": "ca8ad131137b4a75c5789ce7cdb8d07a9f8036b52e89c87c61e5beff2cf9607f", "durationMs": 5365}, "DLG-SC-AKT-SEMBOKU-001-SHARED-07": {"sourceJa": "担当者が帯の長さと着付け方を見ます。今はご自分で新しい印を付けないでください。", "role": "femaleStudent", "speakerId": 8, "clip": "a0516bf01888488817e5db60406c4c74c02d490e997ac8dcc7608904a370114d", "durationMs": 6656}, "DLG-SC-AKT-SEMBOKU-001-SHARED-09": {"sourceJa": "はい。元の形が分かるよう確認してから、ほどいて相談しましょう。", "role": "femaleStudent", "speakerId": 8, "clip": "14585227d3f146a10499af6325f4eba2d80127a50a4e295a0a6850033f6a41d1", "durationMs": 5621}, "DLG-SC-AKT-SEMBOKU-001-SHARED-11": {"sourceJa": "承知しました。着付けの担当へおつなぎします。ご相談ありがとうございます。", "role": "femaleStudent", "speakerId": 8, "clip": "e9dfd88f5600a7bc3a58bcae5e5f0b1187bbae3f5cd85062540a114e15ee5f7f", "durationMs": 6005}}, "SC-LOC-003-05-001": {"DLG-SC-LOC-003-05-001-SHARED-01": {"sourceJa": "いらっしゃいませ。何かお手伝いできますか。", "role": "femaleStudent", "speakerId": 8, "clip": "41d479cf1789825a9cf74a741a81eba86201dbaf9773af601264a72a1f360c7e", "durationMs": 3595}}, "SC-LOC-005-16-001": {"DLG-SC-LOC-005-16-001-SHARED-01": {"sourceJa": "いらっしゃいませ。何かお手伝いできますか。", "role": "femaleStudent", "speakerId": 8, "clip": "41d479cf1789825a9cf74a741a81eba86201dbaf9773af601264a72a1f360c7e", "durationMs": 3595}}, "SC-LOC-006-13-001": {"DLG-SC-LOC-006-13-001-SHARED-01": {"sourceJa": "いらっしゃいませ。何かお手伝いできますか。", "role": "femaleStudent", "speakerId": 8, "clip": "41d479cf1789825a9cf74a741a81eba86201dbaf9773af601264a72a1f360c7e", "durationMs": 3595}}, "SC-LOC-AKT-ODATE-03-001": {"DLG-SC-LOC-AKT-ODATE-03-001-SHARED-01": {"sourceJa": "いらっしゃいませ。何かお手伝いできますか。", "role": "femaleStudent", "speakerId": 8, "clip": "41d479cf1789825a9cf74a741a81eba86201dbaf9773af601264a72a1f360c7e", "durationMs": 3595}}, "SC-LOC-AKT-ODATE-06-001": {"DLG-SC-LOC-AKT-ODATE-06-001-SHARED-01": {"sourceJa": "いらっしゃいませ。何かお手伝いできますか。", "role": "femaleStudent", "speakerId": 8, "clip": "41d479cf1789825a9cf74a741a81eba86201dbaf9773af601264a72a1f360c7e", "durationMs": 3595}}, "SC-LOC-AKT-YUZAWA-03-001": {"DLG-SC-LOC-AKT-YUZAWA-03-001-SHARED-01": {"sourceJa": "いらっしゃいませ。何かお手伝いできますか。", "role": "femaleStudent", "speakerId": 8, "clip": "41d479cf1789825a9cf74a741a81eba86201dbaf9773af601264a72a1f360c7e", "durationMs": 3595}}, "SC-LOC-MYG-MATSUSHIMA-03-001": {"DLG-SC-LOC-MYG-MATSUSHIMA-03-001-SHARED-01": {"sourceJa": "いらっしゃいませ。何かお手伝いできますか。", "role": "femaleStudent", "speakerId": 8, "clip": "41d479cf1789825a9cf74a741a81eba86201dbaf9773af601264a72a1f360c7e", "durationMs": 3595}}, "SC-LOC-MYG-MATSUSHIMA-07-001": {"DLG-SC-LOC-MYG-MATSUSHIMA-07-001-SHARED-01": {"sourceJa": "いらっしゃいませ。何かお手伝いできますか。", "role": "femaleStudent", "speakerId": 8, "clip": "41d479cf1789825a9cf74a741a81eba86201dbaf9773af601264a72a1f360c7e", "durationMs": 3595}}, "SC-LOC-YGT-TSURUOKA-06-001": {"DLG-SC-LOC-YGT-TSURUOKA-06-001-SHARED-01": {"sourceJa": "いらっしゃいませ。何かお手伝いできますか。", "role": "femaleStudent", "speakerId": 8, "clip": "41d479cf1789825a9cf74a741a81eba86201dbaf9773af601264a72a1f360c7e", "durationMs": 3595}}};
